def get_cube_side_length():
    """Ask the user for the side length of a cube and validate the input."""
    while True:
        try:
            side_length = int(input("Enter the side length of the cube: "))
            if side_length > 0:
                return side_length
            else:
                print("The side length must be a positive number. Please try again.")
        except ValueError:
            print("That's not a valid number. Please try again.")

def calculate_cube_volume(side_length):
    """Calculate and print the volume of a cube with the given side length."""
    volume = side_length ** 3
    print(f"The volume of the cube with side length {side_length} is {volume}.")

# Call the functions to get the side length and calculate the volume
side_length = get_cube_side_length()
